// === Tab: mySketch ===
/*
 * ===== #WCCC_Cube =====
 * Made for the weekly creative code challenge hosted by @Sableraph 
 * Discord: discord.gg/h9yJJYwy
 * Twitch: twitch.tv/Sableraph
 * 
 * 
 */


// colors gruvbox theme https://github.com/morhetz/gruvbox
const background_dark = '#282828';
const colors_dark = ['#d79921', '#d65d0e', '#cc241d', '#b16286', '#458588', '#689d6a', '#98971a'];
const colors_dark_b = ['#d79921a0', '#d65d0ea0', '#cc241da0', '#b16286a0', '#458588a0', '#689d6aa0', '#98971aa0'];

const background_light = "#ebdbb2";
const colors_light = ['#b57614', '#af3a03', '#9d0006', '#8f3f71', '#076678', '#427b58', '#79740e'];

const halfSizeOuter = 330;
const halfSizeInner = 180;

const sphereDetail = 10 // higher numbers might impact performance
const sphereDiameter = 25

const nodes = [
	// outer cube
	{x:  halfSizeOuter, y:  halfSizeOuter, z:  halfSizeOuter}, // 0
	{x:  halfSizeOuter, y:  halfSizeOuter, z: -halfSizeOuter}, // 1
	{x:  halfSizeOuter, y: -halfSizeOuter, z:  halfSizeOuter}, // 2
	{x:  halfSizeOuter, y: -halfSizeOuter, z: -halfSizeOuter}, // 3
	{x: -halfSizeOuter, y:  halfSizeOuter, z:  halfSizeOuter}, // 4
	{x: -halfSizeOuter, y:  halfSizeOuter, z: -halfSizeOuter}, // 5
	{x: -halfSizeOuter, y: -halfSizeOuter, z:  halfSizeOuter}, // 6
	{x: -halfSizeOuter, y: -halfSizeOuter, z: -halfSizeOuter}, // 7
	// inner cube
	{x:  halfSizeInner, y:  halfSizeInner, z:  halfSizeInner}, // 8
	{x:  halfSizeInner, y:  halfSizeInner, z: -halfSizeInner}, // 9
	{x:  halfSizeInner, y: -halfSizeInner, z:  halfSizeInner}, // 10
	{x:  halfSizeInner, y: -halfSizeInner, z: -halfSizeInner}, // 11
	{x: -halfSizeInner, y:  halfSizeInner, z:  halfSizeInner}, // 12
	{x: -halfSizeInner, y:  halfSizeInner, z: -halfSizeInner}, // 13
	{x: -halfSizeInner, y: -halfSizeInner, z:  halfSizeInner}, // 14
	{x: -halfSizeInner, y: -halfSizeInner, z: -halfSizeInner}, // 15
]

let walkers = []

const paths = [
	//outer cube connections
	{p1: 0, p2: 1}, 
	{p1: 0, p2: 2}, 
	{p1: 0, p2: 4}, 
	{p1: 1, p2: 3}, 
	{p1: 1, p2: 5}, 
	{p1: 2, p2: 3}, 
	{p1: 2, p2: 6}, 
	{p1: 3, p2: 7}, 
	{p1: 4, p2: 5}, 
	{p1: 4, p2: 6}, 
	{p1: 5, p2: 7}, 
	{p1: 6, p2: 7}, 

	//inner cube connections
	{p1: 8, p2: 9}, 
	{p1: 8, p2: 10}, 
	{p1: 8, p2: 12}, 
	{p1: 9, p2: 11}, 
	{p1: 9, p2: 13}, 
	{p1: 10, p2: 11}, 
	{p1: 10, p2: 14}, 
	{p1: 11, p2: 15}, 
	{p1: 12, p2: 13}, 
	{p1: 12, p2: 14}, 
	{p1: 13, p2: 15}, 
	{p1: 14, p2: 15}, 

	//outer cube - inner cube
	{p1: 0, p2: 8}, 
	{p1: 1, p2: 9}, 
	{p1: 2, p2: 10}, 
	{p1: 3, p2: 11}, 
	{p1: 4, p2: 12}, 
	{p1: 5, p2: 13}, 
	{p1: 6, p2: 14}, 
	{p1: 7, p2: 15}, 
]

const morphPaths = [
	{a: 0, b: 8},
	{a: 1, b: 0},
	{a: 2, b: 10},
	{a: 3, b: 2},
	{a: 4, b: 12},
	{a: 5, b: 4},
	{a: 6, b: 14},
	{a: 7, b: 6},
	{a: 8, b: 9},
	{a: 9, b: 1},
	{a: 10, b: 11},
	{a: 11, b: 3},
	{a: 12, b: 13},
	{a: 13, b: 5},
	{a: 14, b: 15},
	{a: 15, b: 7},
]

let t = 0

function setup() {
	describe("a template for my wccc sketches, it comes with templated comment and the gruvbox color theme")

	createCanvas(windowWidth, windowHeight, WEBGL);
	for(let i = 0; i < colors_dark.length * 2; i++) {
		let path = random(paths);
		walkers.push({
			colorI: i % colors_dark.length,
			p1: path.p1,
			p2: path.p2,
			t: 0,
			speed: map(random(), 0, 1, 0.25, 0.6),
			r: map(i, 0, colors_dark.length, 0.95, 1.05),
		})
	}

	camera(1000, -400, -300, 0, 0, 0)
}

function draw() {

	orbitControl()
	t = (frameCount * 0.002) % 4

	background(background_dark)

	drawBox()


	for(let i = 0; i < walkers.length; i++) {
		updateWalker(i)
		drawWalker(i)
	}
}

function drawBox() {
	noFill();
	stroke(background_light)
	strokeWeight(2)

	for(let i = 0; i < paths.length; i++) {
		let p1 = getMorphedNodePos(paths[i].p1, t)
		let p2 = getMorphedNodePos(paths[i].p2, t)

		line(p1.x, p1.y, p1.z, p2.x, p2.y, p2.z)
	}
}

function getMorphedNodePos(nodeIndex, t, debug = false) {

	let morphPath = morphPaths[nodeIndex] 
	if(debug) {
		console.log(`a: ${morphPath.a}, b: ${morphPath.b}`)
	}
	for(let i = 1; i <= t; i++) {
		morphPath = morphPaths[morphPath.b]

		if(debug) {
			console.log(`a: ${morphPath.a}, b: ${morphPath.b}`)
		}
	}

	let x = lerp(nodes[morphPath.a].x, nodes[morphPath.b].x, easeInOutSine(fract(t)))
	let y = lerp(nodes[morphPath.a].y, nodes[morphPath.b].y, easeInOutSine(fract(t)))
	let z = lerp(nodes[morphPath.a].z, nodes[morphPath.b].z, easeInOutSine(fract(t)))
	return {x, y, z}
}

function getAvailablePaths(nodeIndex) {
	return paths
		.filter(p => p.p1 == nodeIndex || p.p2 == nodeIndex)
		.map(p => (p.p1 == nodeIndex ? {p1: p.p1, p2: p.p2} : {p1: p.p2, p2: p.p1}))
}

function getWalkerPos(walkerIndex) {
	var p1 = getMorphedNodePos(walkers[walkerIndex].p1, t)
	var p2 = getMorphedNodePos(walkers[walkerIndex].p2, t)
	var x = lerp(p1.x, p2.x, easeInOutSine(walkers[walkerIndex].t))
	var y = lerp(p1.y, p2.y, easeInOutSine(walkers[walkerIndex].t))
	var z = lerp(p1.z, p2.z, easeInOutSine(walkers[walkerIndex].t))

	return createVector(x, y, z)
}

function updateWalker(walkerIndex) {
	walkers[walkerIndex].t += deltaTime * 0.001 * walkers[walkerIndex].speed
	if(walkers[walkerIndex].t >= 1.0) {
		walkers[walkerIndex].t = 0.0;
		let options = getAvailablePaths(walkers[walkerIndex].p2).filter(p => p.p2 != walkers[walkerIndex].p1)
		walkers[walkerIndex].p1 = walkers[walkerIndex].p2;
		walkers[walkerIndex].p2 = random(options).p2;
	}
}

function drawWalker(walkerIndex) {
	p = getWalkerPos(walkerIndex)
	push()
	translate(p.x, p.y, p.z)
	fill(colors_dark[walkers[walkerIndex].colorI])
	noStroke()
	sphere(sphereDiameter * walkers[walkerIndex].r, sphereDetail, sphereDetail)
	pop()
}

function easeInOutSine(x) {
	return -(Math.cos(Math.PI * x) - 1) / 2;
}

// Resize the canvas when the
// browser's size changes.
function windowResized() {
	resizeCanvas(windowWidth, windowHeight);
}

let inspect = 0;

function keyPressed() {
	if(keyCode == 70) {
		let fs = fullscreen();
	    fullscreen(!fs);
	}
}
